import argparse
import json

def main():
    parser = argparse.ArgumentParser(description='Проверка лицензий компонентов')
    parser.add_argument('--json', action='store_true', help='выводить только JSON-объект с итогами')
    args = parser.parse_args()

    allowed_licenses = {
        'MIT', 'BSD-3-Clause', 'Apache-2.0', 'Public Domain', 'Проприетарная'
    }
    allowed_count = 0
    needs_review_count = 0

    with open('компоненты.csv', 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f, delimiter=';')
        next(reader, None)  # пропустить заголовок
        for row in reader:
            if len(row) < 2:
                continue
            component = row[0].strip()
            license_ = row[1].strip()
            if license_ in allowed_licenses:
                status = 'допустима'
                allowed_count += 1
            else:
                status = 'требует проверки'
                needs_review_count += 1
            print(f'{component} — {license_} — {status}')

    if args.json:
        print(json.dumps({"допустимо": allowed_count, "требует_проверки": needs_review_count}, ensure_ascii=False))
    else:
        print(f'Итого: допустимо — {allowed_count}, требует проверки — {needs_review_count}')

if __name__ == '__main__':
    main()", "path": "проверка_лицензий.py"}

